const KNOWLEDGE_PAGE: &str = include_str!("../static/knowledge.html");
const DEFAULT_HISTORY_LIMIT: i64 = 30;
const MAX_HISTORY_LIMIT: i64 = 100;
const DEFAULT_REVALIDATION_QUEUE_LIMIT: i64 = 30;
const MAX_REVALIDATION_QUEUE_LIMIT: i64 = 100;

#[derive(Clone)]
pub struct KnowledgeApiState {
    knowledge: Arc<KnowledgeStore>,
    fleet: Arc<FleetStore>,
    tenant_id: Arc<str>,
}

impl KnowledgeApiState {
    pub fn new(
        knowledge: Arc<KnowledgeStore>,
        fleet: Arc<FleetStore>,
        tenant_id: Arc<str>,
    ) -> Self {
        Self {
            knowledge,
            fleet,
            tenant_id,
        }
    }
}

pub fn knowledge_routes(state: KnowledgeApiState) -> Router {
    Router::new()
        .route("/knowledge", get(knowledge_page))
        .route(
            "/api/v1/repositories/:repository_id/knowledge/history",
            get(knowledge_history),
        )
        .route(
            "/api/v1/repositories/:repository_id/knowledge/revalidation-queue",
            get(revalidation_queue),
        )
        .with_state(state)
}

